(() => {
  const pathParts=location.pathname.split('/').filter(Boolean);
  const lastPart=(pathParts.pop()||'').toLowerCase();
  const folder=(lastPart==='index.html' ? (pathParts.pop()||'') : lastPart).toLowerCase();
  const n=parseInt(folder.slice(0,2),10);
  const img={idea:'../shared/assets/ideation-world.png',product:'../shared/assets/product-development-world.png',forms:'../shared/assets/business-forms-world.png',launch:'../shared/assets/enterprise-launch-world.png'};
  const common={
    kicker:'Unit II · Creating Entrepreneurial Venture',
    imageAlt:'Illustrated Indian entrepreneurship learning environment',
    complete:{title:'You can use this decision in a real venture',message:'Your work shows that you can explain the concept and use it in a practical founder situation.',takeaways:[],transfer:''}
  };
  const lessons={
  3:{title:'SCAMPER Makeover Lab',subtitle:'Transform an ordinary product into a stronger opportunity—one purposeful change at a time.',mission:'Use all seven SCAMPER lenses to redesign a reusable lunch box for college students.',image:img.idea,context:'A student innovation studio in Coimbatore is improving an everyday product.',learn:{why:'SCAMPER gives you seven clear prompts when “think of something new” feels too vague.',steps:[{title:'Start with something real',text:'Choose an existing product, service or process. SCAMPER improves a starting point; it does not require a blank page.'},{title:'Ask one change question',text:'Use Substitute, Combine, Adapt, Modify, Put to another use, Eliminate or Reverse.'},{title:'Judge the benefit',text:'Keep a change only when it solves a customer problem or creates useful value.'}],terms:[{term:'SCAMPER',meaning:'Seven structured ways to transform an existing idea.'},{term:'Customer benefit',meaning:'The practical improvement the user experiences—not merely a technical feature.'}],example:'Eliminate disposable packaging from a snack service. The feature is “returnable containers”; the customer benefit is lower waste and repeat-order convenience.'},activity:{mode:'explore',max:7,heading:'The seven-tool workbench',intro:'The product is a reusable lunch box for college students.',instruction:'Open each tool, read its question, write one useful modification and save it. Apply all seven tools before continuing.',items:[{name:'Substitute',meaning:'Replace a material, part, person or process.',question:'What can be replaced to improve safety, cost or convenience?',example:'Replace a breakable inner container with food-grade stainless steel.'},{name:'Combine',meaning:'Join two functions or products.',question:'What useful functions can work together?',example:'Combine the lunch box with a removable phone stand.'},{name:'Adapt',meaning:'Borrow a useful feature from another context.',question:'What idea elsewhere could fit this product?',example:'Adapt the insulation used in travel flasks.'},{name:'Modify',meaning:'Change size, shape, colour or performance.',question:'What can be enlarged, reduced or reshaped?',example:'Use adjustable partitions for different meal sizes.'},{name:'Put to another use',meaning:'Find another user or purpose.',question:'Who else could use it, and for what?',example:'Use one compartment as a seed-starting tray after the product’s life.'},{name:'Eliminate',meaning:'Remove complexity, waste or unnecessary parts.',question:'What can disappear without harming value?',example:'Eliminate loose cutlery using a spoon built into the lid.'},{name:'Reverse',meaning:'Reorder, invert or turn the normal process around.',question:'What happens if the sequence or arrangement is reversed?',example:'Let the base become the serving plate instead of adding a plate.'}]},apply:{heading:'Build your improved concept',intro:'Select the strongest change—not necessarily the most unusual one.',outputName:'SCAMPER concept card',outputIntro:'Review the logic below. You may return and revise it before completion.',fields:[{label:'Chosen SCAMPER move',help:'Name the lens and the exact change.',placeholder:'Example: Combine — add a removable phone stand…'},{label:'Customer problem solved',help:'Explain the difficulty this removes.',placeholder:'Students currently struggle to…'},{label:'Customer benefit',help:'State the practical result for the user.',placeholder:'This helps students by…'}]},complete:{...common.complete,takeaways:['SCAMPER begins with an existing product or process.','Each lens prompts a different type of change.','A modification becomes useful innovation only when it creates customer value.'],transfer:'Which SCAMPER lens would be most useful for improving a service rather than a physical product? Why?'}},
  4:{title:'Idea Funnel Challenge',subtitle:'Many ideas can enter. Only evidence-backed opportunities should leave the funnel.',mission:'Compare four campus venture ideas and choose the one with the best balance of desirability, feasibility and viability.',image:img.idea,context:'A student team has limited time and funds for one pilot venture.',learn:{why:'A founder cannot develop every idea. Screening reduces emotional bias and directs resources towards a stronger opportunity.',steps:[{title:'Define the criteria',text:'Desirability asks whether customers care; feasibility asks whether the team can deliver; viability asks whether the venture can sustain itself.'},{title:'Rate with evidence',text:'Give each criterion a score only after looking for observations, skills, costs and likely revenue.'},{title:'Select and test',text:'The funnel chooses a test-worthy idea—not a guaranteed success.'}],terms:[{term:'Idea screening',meaning:'Comparing ideas using agreed criteria before committing major resources.'},{term:'Viability',meaning:'The ability of a venture to generate enough value and revenue to continue.'}],example:'A high-demand food app may be desirable, but without delivery capacity it is not yet feasible. A small campus pre-order pilot could improve feasibility.'},activity:{mode:'funnel',max:3,heading:'Score the opportunity cards',intro:'Use the case evidence—not personal preference—to set three ratings for each idea.',instruction:'Adjust all three sliders on each card. Then send the strongest idea through the funnel and read the feedback.',best:1,success:'The repair service has an observed problem, available technical skills and a low-cost pilot route. It is the strongest test candidate.',retry:'Compare whether the problem is observed, whether the team can deliver now and whether customers are likely to pay.',ideas:[{name:'Premium drone café delivery',desc:'Students say it sounds exciting. The team has no drone permission process, aircraft or delivery budget.'},{name:'Hostel appliance repair desk',desc:'Repeated repair requests are visible. Two students have the skills, and customers already pay outside technicians.'},{name:'AR campus tour',desc:'Interesting technology and available coding skill, but no paying customer or urgent user problem is identified.'},{name:'Custom merchandise stockroom',desc:'Some demand exists, but minimum order quantities create high unsold-inventory risk.'}]},apply:{heading:'Write your screening decision',intro:'Turn scores into a short, defensible founder decision.',outputName:'idea screening note',outputIntro:'This note records why the idea deserves a small test.',fields:[{label:'Selected idea',help:'State the idea clearly.',placeholder:'I would test…'},{label:'Best evidence',help:'Mention one desirability, feasibility and viability signal.',placeholder:'Customers…, our team…, and revenue…'},{label:'First low-cost test',help:'Describe what you would do before investing heavily.',placeholder:'For one week, we will…'}]},complete:{...common.complete,takeaways:['Desirability, feasibility and viability answer different questions.','Scores should be supported by evidence.','Screening selects what to test next, not what is guaranteed to succeed.'],transfer:'If the most desirable idea is not feasible today, what small experiment could reduce the uncertainty?'}},
  5:{title:'Customer Interview Simulator',subtitle:'Learn to hear evidence instead of accidentally collecting polite praise.',mission:'Interview a potential user about a placement-preparation service without leading them towards your idea.',image:img.idea,context:'A founder is exploring a service for final-year engineering students.',learn:{why:'Customer conversations can reveal real behaviour, but leading questions often produce unreliable compliments.',steps:[{title:'Ask about the past',text:'Past actions and specific incidents are stronger evidence than guesses about future behaviour.'},{title:'Stay neutral',text:'Do not tell the customer what answer you hope to hear.'},{title:'Probe for commitment',text:'Time, effort, money and repeated workarounds show how important the problem is.'}],terms:[{term:'Leading question',meaning:'A question that suggests or pressures the respondent towards a preferred answer.'},{term:'Behavioural evidence',meaning:'What the customer actually did, spent or tried in a real situation.'}],example:'Weak: “Would you use our amazing app?” Strong: “Tell me about the last time you prepared for an aptitude test.”'},activity:{mode:'branch',max:3,heading:'Conduct the interview',intro:'Your evidence, rapport and bias meters will respond to each question.',instruction:'Choose the most useful question at each stage. Read why it strengthens or weakens the interview.',scenes:[{speaker:'Ananya · final-year student',line:'Placement tests are stressful. I sometimes prepare at the last minute.',choices:[{text:'Would you pay for my AI placement app?',good:false,delta:{bias:22,rapport:-8},feedback:'This introduces your solution too early and asks for a prediction. The student may respond politely.'},{text:'Tell me about the last test you prepared for.',good:true,delta:{evidence:22,rapport:8,bias:-12},feedback:'A specific past event is easier to recall and gives behavioural evidence.'},{text:'You agree colleges should provide better training, right?',good:false,delta:{bias:25,evidence:-5},feedback:'The wording suggests the expected answer.'}]},{speaker:'Ananya',line:'Last month I used free videos for two nights, but I could not identify my weak topics.',choices:[{text:'What did you do when you could not identify them?',good:true,delta:{evidence:25,rapport:6,bias:-8},feedback:'This explores the existing workaround and the seriousness of the problem.'},{text:'Our dashboard will solve that. Do you like it?',good:false,delta:{bias:20,rapport:-4},feedback:'This changes discovery into a sales pitch before the need is understood.'},{text:'How many colours should the dashboard have?',good:false,delta:{evidence:-8,bias:10},feedback:'Interface detail is premature; the problem and willingness to act are still uncertain.'}]},{speaker:'Ananya',line:'I finally paid ₹300 for a mock test and used it twice.',choices:[{text:'What made that worth paying for, and what disappointed you?',good:true,delta:{evidence:28,rapport:8,bias:-8},feedback:'Payment and actual usage are strong signals. Asking about both value and disappointment keeps the question balanced.'},{text:'So ₹300 is the perfect price for everyone?',good:false,delta:{bias:17,evidence:-6},feedback:'One purchase does not establish a universal price.'},{text:'If we build it, will you definitely subscribe?',good:false,delta:{bias:18,rapport:-5},feedback:'A promise about future behaviour is weaker than a small real commitment or pilot.'}]}]},apply:{heading:'Prepare your next interview',intro:'Write neutral questions for a venture problem you want to investigate.',outputName:'customer interview guide',outputIntro:'Use this guide to learn before you pitch.',fields:[{label:'Customer group and problem area',help:'Do not include your solution yet.',placeholder:'Final-year students who struggle to…'},{label:'Past-behaviour question',help:'Ask about one specific recent incident.',placeholder:'Tell me about the last time…'},{label:'Evidence probe',help:'Ask about time, money, effort or an existing workaround.',placeholder:'What did you try, and what did it cost…'}]},complete:{...common.complete,takeaways:['Past behaviour is stronger than hypothetical praise.','Neutral questions reduce interviewer bias.','Time, money and workarounds reveal problem importance.'],transfer:'What answer would make you decide not to build your current idea?'}},
  6:{title:'Creative Problem-Solving Sprint',subtitle:'Move from a confusing situation to an action that can be tested.',mission:'Arrange and apply the four creative problem-solving stages to reduce long queues at a campus service counter.',image:img.product,context:'Students wait too long to collect routine documents during peak hours.',learn:{why:'Creative problem-solving separates understanding the problem from generating and implementing solutions.',steps:[{title:'Clarify',text:'Gather facts, define the users and frame the right problem.'},{title:'Ideate and develop',text:'Generate multiple options, then strengthen and select promising ones.'},{title:'Implement',text:'Convert the chosen concept into a small action, owner, measure and review point.'}],terms:[{term:'Divergent thinking',meaning:'Creating many possible answers before judging them.'},{term:'Convergent thinking',meaning:'Comparing options and selecting or improving the strongest.'}],example:'Clarify “queue is long” using time data; ideate appointment slots; develop a low-tech token pilot; implement it for one week and measure waiting time.'},activity:{mode:'sequence',max:4,heading:'Rebuild the problem-solving pathway',intro:'The stage cards are deliberately out of order.',instruction:'Use the arrow buttons to place the stages in the correct learning sequence. Then check your roadmap.',success:'The sequence protects the team from solving the wrong problem or jumping from the first idea straight to full implementation.',retry:'First understand the problem, then widen the options, strengthen a choice and finally test it.',items:[{name:'Implement',clue:'Create an action plan, run a pilot and measure the result.',order:4,start:0},{name:'Ideate',clue:'Generate many possible responses without judging too early.',order:2,start:1},{name:'Clarify',clue:'Collect facts and define the actual challenge.',order:1,start:2},{name:'Develop',clue:'Compare, combine and strengthen promising options.',order:3,start:3}]},apply:{heading:'Frame a four-stage sprint',intro:'Choose a familiar problem and show how the process will guide action.',outputName:'creative problem-solving sprint card',outputIntro:'This is your short path from ambiguity to evidence.',fields:[{label:'Clarified problem',help:'Name the user, situation and observable difficulty.',placeholder:'During…, users… because…'},{label:'Ideas to explore',help:'List at least two different approaches.',placeholder:'Option 1…, Option 2…'},{label:'Pilot and measure',help:'State the smallest action and one success measure.',placeholder:'We will test… and measure…'}]},complete:{...common.complete,takeaways:['Clarify before ideating.','Divergent thinking creates options; convergent thinking improves and selects.','Implementation should begin with a measurable pilot.'],transfer:'Where could premature solution selection damage a student venture?'}},
  7:{title:'Root-Cause Investigation',subtitle:'Do not repair the symptom and leave the real failure untouched.',mission:'Investigate why a campus 3D-printing service repeatedly delivers parts late.',image:img.product,context:'A student-run fabrication service is receiving complaints despite adding overtime.',learn:{why:'A visible symptom may have several deeper causes. Root-cause analysis helps a team act where change will prevent recurrence.',steps:[{title:'Observe the symptom',text:'Describe what is happening without guessing why.'},{title:'Build the cause chain',text:'Ask what conditions produced the symptom and continue until the team reaches an actionable system cause.'},{title:'Verify before acting',text:'Use logs, observation, interviews or tests to confirm the suspected cause.'}],terms:[{term:'Symptom',meaning:'The visible effect of a problem.'},{term:'Root cause',meaning:'A deeper, actionable condition whose removal reduces recurrence.'}],example:'Symptom: parts arrive late. Immediate cause: repeated print failures. Root cause: jobs are accepted without checking material availability and machine condition.'},activity:{mode:'detective',max:6,heading:'Sort the investigation evidence',intro:'Each statement plays a different role in the cause chain.',instruction:'Classify every card as Symptom, Immediate cause or Root cause. Feedback will explain the best fit.',categories:['Symptom','Immediate cause','Root cause'],evidence:[{text:'Customers receive printed parts two days after the promised date.',answer:'Symptom',feedback:'This is the visible outcome experienced by the customer.'},{text:'Several jobs must be restarted after layer separation.',answer:'Immediate cause',feedback:'Print restarts directly increase production time.'},{text:'Operators do not check material dryness before starting long jobs.',answer:'Root cause',feedback:'This is an actionable process weakness that contributes to repeat failure.'},{text:'The order board shows many urgent jobs at the same time.',answer:'Symptom',feedback:'It shows overload, but further investigation is needed to explain why commitments exceed capacity.'},{text:'Job quotations are issued without checking machine-hour availability.',answer:'Root cause',feedback:'The planning system permits unrealistic promises and repeated overload.'},{text:'One printer remained idle because a nozzle was blocked.',answer:'Immediate cause',feedback:'The blockage directly removed capacity; the maintenance process may be the deeper cause.'}]},apply:{heading:'Create a cause brief',intro:'Use the distinction between observation and explanation.',outputName:'root-cause investigation brief',outputIntro:'Treat the root cause as a hypothesis until evidence confirms it.',fields:[{label:'Observed symptom',help:'State what can be seen or measured.',placeholder:'Users experience…'},{label:'Likely cause chain',help:'Write “because” at least twice.',placeholder:'This happens because…, which happens because…'},{label:'Verification test',help:'Identify the evidence that would confirm or reject your suspected root cause.',placeholder:'We will review/observe/measure…'}]},complete:{...common.complete,takeaways:['Symptoms describe effects; causes explain them.','A root cause should be deep enough to prevent recurrence but still actionable.','Evidence must verify the cause before major action.'],transfer:'Why is “the employee was careless” usually a weak stopping point in root-cause analysis?'}},
  8:{title:'Product Development Roadmap',subtitle:'Turn an idea into a tested offering through evidence-based stage gates.',mission:'Arrange the product-development journey for a low-cost smart irrigation controller.',image:img.product,context:'A Coimbatore team wants to serve small farms without scaling an untested design.',learn:{why:'A staged process reduces technical, customer and financial uncertainty before commercial launch.',steps:[{title:'Shape the opportunity',text:'Begin with the user problem, idea generation and initial screening.'},{title:'Plan and prototype',text:'Translate customer requirements into a concept, resources, schedule and testable prototype.'},{title:'Validate and launch',text:'Use technical and customer evidence before committing to commercialisation.'}],terms:[{term:'Prototype',meaning:'A testable representation used to learn—not necessarily a finished product.'},{term:'Stage gate',meaning:'A decision point where evidence is reviewed before more resources are committed.'}],example:'Before manufacturing 500 controllers, test a small prototype for sensing accuracy, installation time and farmer willingness to pay.'},activity:{mode:'sequence',max:7,heading:'Build the development journey',intro:'Each stage should reduce a different uncertainty.',instruction:'Move the cards into the most logical order from opportunity to commercialisation, then check the roadmap.',success:'The roadmap moves from problem and concept evidence towards technical validation and commercial commitment.',retry:'Ask what must be understood before planning, what must be built before testing and what must be validated before launch.',items:[{name:'Commercialisation',clue:'Prepare production, market launch, sales and support.',order:7,start:0},{name:'Concept development',clue:'Translate the opportunity into solution alternatives and customer requirements.',order:3,start:1},{name:'Product testing',clue:'Validate technical performance and customer response.',order:6,start:2},{name:'Opportunity identification',clue:'Define the customer problem and context.',order:1,start:3},{name:'Prototype development',clue:'Create a testable form of the selected concept.',order:5,start:4},{name:'Idea screening',clue:'Compare alternatives and select a test candidate.',order:2,start:5},{name:'Product planning',clue:'Define features, resources, risks, schedule and business logic.',order:4,start:6}]},apply:{heading:'Design one stage gate',intro:'Show what evidence your product needs before moving forward.',outputName:'product stage-gate card',outputIntro:'A clear gate prevents enthusiasm from replacing evidence.',fields:[{label:'Product and current stage',help:'State what is being developed and where it is now.',placeholder:'Our product is… and it is currently at…'},{label:'Evidence required',help:'Include technical and customer evidence.',placeholder:'Before proceeding, we need to prove…'},{label:'Go / revise / stop rule',help:'State the decision threshold in plain language.',placeholder:'We will proceed only if…'}]},complete:{...common.complete,takeaways:['Product development reduces uncertainty in stages.','A prototype is built to learn.','Stage gates connect evidence to resource decisions.'],transfer:'What could happen if a team commercialises immediately after building its first working prototype?'}},
  9:{title:'Product Trade-off Simulator',subtitle:'Balance what customers want with what the venture can reliably deliver.',mission:'Tune a student safety wearable without making it too costly, slow or complex to launch.',image:img.product,context:'A product team has a promising concept but cannot maximise every feature at once.',learn:{why:'Improving one product dimension can weaken another. Founders must make explicit, evidence-led compromises.',steps:[{title:'Name the priorities',text:'Identify which customer outcomes are essential and which are optional.'},{title:'See the constraints',text:'Cost, time, technical ability and reliability limit the feasible design space.'},{title:'Choose a balanced promise',text:'Deliver the smallest dependable set of benefits that customers value.'}],terms:[{term:'Trade-off',meaning:'Accepting less of one benefit to gain or protect another.'},{term:'Scope',meaning:'The features and work included in a particular product release.'}],example:'Adding live video may increase perceived value, but it also raises battery use, cost and development time. A reliable alert and location feature may be the better first release.'},activity:{mode:'simulator',max:5,heading:'Tune the first release',intro:'The highest setting on every slider is not the best product.',instruction:'Adjust the four controls to balance user value and delivery constraints. Aim for a fit score of 82% or above.',consoleTitle:'Release-control console',consoleHelp:'Targets represent evidence from users and the team’s present capability.',pass:82,startFeedback:'Change one factor at a time and notice how distance from the evidence-based target affects fit.',success:'This release protects the essential benefit while keeping cost, reliability and development effort realistic.',retry:'Reduce unnecessary scope or rebalance price, reliability and delivery time around the target evidence.',controls:[{key:'features',label:'Feature scope',min:1,max:10,value:8,target:5,weight:5},{key:'price',label:'Customer price',min:1,max:10,value:3,target:5,weight:4},{key:'reliability',label:'Reliability effort',min:1,max:10,value:5,target:8,weight:5},{key:'speed',label:'Launch speed',min:1,max:10,value:9,target:6,weight:4}]},apply:{heading:'Record your product compromise',intro:'Explain a trade-off so the team understands what is protected and what is postponed.',outputName:'first-release decision',outputIntro:'A useful product decision is clear about both inclusion and exclusion.',fields:[{label:'Essential customer outcome',help:'State the result the first release must deliver.',placeholder:'The product must reliably help users…'},{label:'Feature postponed or reduced',help:'Name what will not be maximised now.',placeholder:'We will postpone/reduce…'},{label:'Reason and evidence',help:'Connect the decision to cost, time, reliability or customer evidence.',placeholder:'Because our evidence shows…'}]},complete:{...common.complete,takeaways:['More features do not automatically create more value.','Trade-offs should protect essential customer outcomes.','A focused first release can improve reliability and learning speed.'],transfer:'Which trade-off would you never make in a safety-critical product, and why?'}},
  10:{title:'Business Forms Decision Matrix',subtitle:'Choose an ownership form by matching its consequences to the venture—not by choosing a familiar label.',mission:'Compare sole proprietorship, partnership, LLP and corporation across five founder priorities.',image:img.forms,context:'Four founders are seeking advice for ventures with different risk, capital and continuity needs.',learn:{why:'The form of business affects control, liability, continuity, compliance and the ability to raise capital.',steps:[{title:'Understand the venture',text:'Clarify ownership, risk, scale ambition, funding need and continuity.'},{title:'Compare consequences',text:'Look beyond formation convenience to responsibility, governance and future needs.'},{title:'Choose and justify',text:'Select the closest fit and seek professional advice for actual registration.'}],terms:[{term:'Liability',meaning:'Legal responsibility for business debts and obligations.'},{term:'Continuity',meaning:'Whether the business can continue despite a change in owner or member.'}],example:'A low-risk solo local service may value simple control. A technology venture seeking investors and long-term continuity may need a company structure.'},activity:{mode:'matrix',max:4,heading:'Read the matrix, then advise four founders',intro:'The table gives a simplified educational comparison.',instruction:'Use the matrix and the stated priority in each case. Choose a form and read the consequence-based feedback.',forms:['Sole proprietorship','Partnership','LLP','Corporation'],rows:[{factor:'Owners',values:['One','Two or more','Two or more partners','Shareholders']},{factor:'Liability',values:['Generally unlimited','Generally unlimited','Limited for partners','Limited for shareholders']},{factor:'Continuity',values:['Closely tied to owner','Affected by partnership terms','Separate legal entity','Separate legal entity']},{factor:'Compliance',values:['Relatively low','Moderate','Higher than partnership','Generally higher']},{factor:'Capital route',values:['Owner/borrowings','Partners/borrowings','Partner contribution/borrowings','Shares and other routes']}],cases:[{case:'Meena runs a small, low-risk tailoring service alone.',need:'Priority: direct control and simple initial administration.',answer:0,feedback:'A sole proprietorship can fit a small solo venture, though the owner must understand personal liability.'},{case:'Two friends begin a short-duration event service and accept shared personal responsibility.',need:'Priority: a simple jointly owned arrangement supported by a clear agreement.',answer:1,feedback:'A partnership can fit, but roles, profit sharing and exit terms should be written clearly.'},{case:'Three consultants want a separate entity and limited liability while operating through partners.',need:'Priority: professional flexibility with limited liability.',answer:2,feedback:'An LLP aligns with those stated priorities, subject to applicable legal and professional advice.'},{case:'A scalable technology venture plans to issue equity to investors.',need:'Priority: capital access, ownership transfer and continuing entity.',answer:3,feedback:'A company/corporation structure is generally better aligned with equity investment and continuity.'}]},apply:{heading:'Write a founder recommendation',intro:'Use consequences and priorities—not vague claims such as “this is best”.',outputName:'business-form recommendation',outputIntro:'This is an educational decision note, not legal advice.',fields:[{label:'Venture profile',help:'State owners, risk and scale ambition.',placeholder:'This venture has… owners, faces… risk and aims to…'},{label:'Recommended form',help:'Choose one form from the lesson.',placeholder:'I recommend…'},{label:'Reason and caution',help:'Give two matching factors and one issue to verify professionally.',placeholder:'It fits because… The founders should verify…'}]},complete:{...common.complete,takeaways:['Business form changes liability, control, continuity and capital options.','No single form is best for every venture.','Actual formation decisions require current legal and professional verification.'],transfer:'How might the most suitable form change when a local venture begins seeking outside equity?'}},
  11:{title:'Sole Proprietor Decision Desk',subtitle:'Decide when simplicity and control outweigh continuity and personal-risk concerns.',mission:'Advise a founder opening a mobile bicycle-repair service in Coimbatore.',image:img.forms,context:'Arun plans to start alone, test demand locally and use modest personal savings.',learn:{why:'Sole proprietorship is easy to understand but the owner and business are closely connected.',steps:[{title:'Check the fit',text:'Look for one owner, manageable risk, modest capital need and a need for direct control.'},{title:'Recognise exposure',text:'The owner generally bears business obligations personally and continuity depends strongly on the owner.'},{title:'Plan the transition',text:'A simple starting form can be reviewed if risk, team size or capital needs grow.'}],terms:[{term:'Proprietor',meaning:'The individual who owns and controls a sole proprietorship.'},{term:'Unlimited liability',meaning:'Business obligations may reach the owner’s personal assets, subject to applicable law.'}],example:'A solo repair pilot may value simple control. If it expands into product manufacturing with employees and large contracts, the risk profile changes and the form should be reviewed.'},activity:{mode:'branch',max:3,heading:'Advise Arun through three decisions',intro:'The control, risk and readiness implications are explained after each choice.',instruction:'Choose the advice that best matches the evidence at each point. This is an educational scenario, not legal advice.',scenes:[{speaker:'Arun',line:'I will work alone for six months, take bookings by phone and use tools I already own.',choices:[{text:'A sole proprietorship can be a reasonable pilot form.',good:true,delta:{evidence:20,rapport:8,bias:-5},feedback:'The small solo test and direct control are compatible with a sole proprietorship.'},{text:'You must form a corporation immediately.',good:false,delta:{bias:14,evidence:-6},feedback:'The advice ignores the venture’s current scale and does not explain why higher formality is needed.'},{text:'The business form never matters for a small venture.',good:false,delta:{evidence:-10,bias:12},feedback:'Even a small venture has liability, tax, licensing and continuity implications.'}]},{speaker:'Arun',line:'A hotel now wants a large annual maintenance contract with penalty clauses.',choices:[{text:'Accept immediately; personal risk is irrelevant.',good:false,delta:{evidence:-8,bias:18},feedback:'A larger contractual exposure changes the risk decision.'},{text:'Review liability, insurance, contract terms and business form before signing.',good:true,delta:{evidence:25,rapport:6,bias:-6},feedback:'The decision responds to the increased exposure rather than relying on the original setup.'},{text:'Reject every growth opportunity permanently.',good:false,delta:{rapport:-8},feedback:'The goal is to manage risk, not avoid all growth.'}]},{speaker:'Arun',line:'Next year I may add two co-founders and seek investment for service vehicles.',choices:[{text:'Keep the same form automatically forever.',good:false,delta:{bias:15,evidence:-6},feedback:'Ownership and funding needs have changed, so the form should be reviewed.'},{text:'Add them informally without documenting ownership.',good:false,delta:{evidence:-10},feedback:'Unclear ownership can create disputes and poor accountability.'},{text:'Reassess partnership, LLP or company options with professional advice.',good:true,delta:{evidence:25,rapport:8,bias:-8},feedback:'A transition review matches the new team, capital and risk profile.'}]}]},apply:{heading:'Prepare a sole-proprietor suitability check',intro:'State both the fit and the limitation.',outputName:'sole-proprietor decision note',outputIntro:'Good advice includes a review trigger as the venture changes.',fields:[{label:'Why the form fits now',help:'Mention ownership, scale or control.',placeholder:'It fits the present stage because…'},{label:'Main risk or limitation',help:'Mention liability, continuity or capital.',placeholder:'The founder must recognise…'},{label:'Trigger to review the form',help:'Name a future change that requires reassessment.',placeholder:'Review the structure when…'}]},complete:{...common.complete,takeaways:['Sole proprietorship offers direct control and relative simplicity.','The owner must understand personal exposure and continuity limits.','Business form should be reassessed as risk, ownership or funding changes.'],transfer:'What measurable growth trigger would make a sole founder review the business form?'}},
  12:{title:'Partnership vs LLP',subtitle:'Two shared-ownership routes can create very different risk and continuity consequences.',mission:'Help two engineering consultants choose between a traditional partnership and an LLP.',image:img.forms,context:'Priya and Farhan will jointly deliver automation projects to industrial clients.',learn:{why:'Shared ownership requires clear roles and agreements. Liability and legal identity can materially change the risk.',steps:[{title:'Map the relationship',text:'Clarify contribution, authority, profit sharing, decisions and exit.'},{title:'Compare structures',text:'A partnership is generally simpler; an LLP provides separate legal identity and limited liability with additional compliance.'},{title:'Document and review',text:'A written agreement and current professional advice remain essential.'}],terms:[{term:'Partnership deed/agreement',meaning:'A written record of partner rights, duties, contributions, sharing and exit arrangements.'},{term:'LLP',meaning:'A Limited Liability Partnership—a separate legal entity with partner-based management.'}],example:'Consultants handling substantial client equipment may value limited liability and continuity enough to accept LLP compliance.'},activity:{mode:'compare',max:3,heading:'Compare consequences, then decide',intro:'Focus on the priority stated in each client situation.',instruction:'Read both panels. Choose Partnership or LLP for each case and study the reasoning.',options:[{name:'Partnership',summary:'A jointly owned arrangement governed by agreement and partnership law.',points:['Generally simpler structure','Partners generally have unlimited liability','Continuity depends more strongly on agreement and partners','Clear deed is essential']},{name:'LLP',summary:'A separate legal entity combining partner operation with limited liability.',points:['Limited liability for partners','Separate legal identity and continuity','Formal registration and continuing compliance','Agreement still defines internal rights']}],cases:[{case:'A temporary, low-risk local event service',need:'The partners accept personal responsibility and prioritise a simple arrangement.',answer:0,feedback:'The stated simplicity and accepted risk align more closely with partnership, provided the agreement is clear.'},{case:'An engineering consultancy signs high-value industrial contracts',need:'The founders prioritise limited liability and continuity.',answer:1,feedback:'An LLP better matches limited-liability and separate-entity priorities, subject to professional advice.'},{case:'One founder may leave while the organisation continues with new partners',need:'Continuity of the entity is a major priority.',answer:1,feedback:'The LLP’s separate legal identity generally supports continuity more clearly than an ordinary partnership.'}]},apply:{heading:'Draft the co-founder decision',intro:'Make the priority and consequence visible.',outputName:'Partnership–LLP comparison note',outputIntro:'Use this as a discussion document before professional consultation.',fields:[{label:'Founders and activity',help:'State who owns the venture and what risks it faces.',placeholder:'The venture is owned by… and undertakes…'},{label:'Chosen route and priority',help:'Choose Partnership or LLP and name the deciding priority.',placeholder:'We prefer… because our priority is…'},{label:'Agreement point to document',help:'Name one role, money or exit rule.',placeholder:'The agreement must clearly state…'}]},complete:{...common.complete,takeaways:['Both forms require a clear founder agreement.','LLP adds separate legal identity and limited liability with more compliance.','The decision should match risk, continuity and administrative capacity.'],transfer:'Why can limited liability never replace professional conduct, insurance and clear contracts?'}},
  13:{title:'Corporation or Franchise?',subtitle:'Choose whether to build an independent scalable organisation or operate within an established system.',mission:'Tune the growth priorities of a food entrepreneur and identify the logic behind corporation and franchise routes.',image:img.forms,context:'Kavya wants to expand beyond one outlet but must decide how much autonomy, capital and system support she needs.',learn:{why:'Corporation and franchising answer different questions: one is an ownership/legal form; the other is a growth arrangement using another firm’s brand and system.',steps:[{title:'Separate the concepts',text:'A corporation/company is a legal ownership structure. A franchise is a contractual right to use a franchisor’s brand and system.'},{title:'Identify priorities',text:'Compare autonomy, brand support, capital route, standardisation and growth speed.'},{title:'Examine obligations',text:'Both routes involve governance, compliance and professional review; a franchise also brings fees and operating rules.'}],terms:[{term:'Corporation/company',meaning:'A separate legal entity owned through shares, subject to applicable company law.'},{term:'Franchise',meaning:'A contractual arrangement allowing a franchisee to use an established brand and operating system.'}],example:'A founder creating a novel food brand may prioritise autonomy and use a company structure. A founder wanting a tested format and known brand may consider a franchise.'},activity:{mode:'simulator',max:5,heading:'Tune Kavya’s growth priorities',intro:'The scenario target represents a founder who wants fast market entry and system support more than complete creative control.',instruction:'Adjust the controls to match the scenario evidence. Reach a fit score of 82% or more.',consoleTitle:'Growth-route console',consoleHelp:'Low autonomy plus high brand support and standardisation point towards a franchise-style route.',pass:82,startFeedback:'Do not choose by popularity. Match the route to what the founder is willing to gain and give up.',success:'Your settings match a franchise-oriented priority profile: established system and speed are valued more than full autonomy.',retry:'Read the scenario again. Increase system support, standardisation and speed; reduce the need for full autonomy.',controls:[{key:'autonomy',label:'Need for autonomy',min:1,max:10,value:8,target:3,weight:4},{key:'support',label:'Need for brand/system support',min:1,max:10,value:4,target:9,weight:5},{key:'standard',label:'Acceptance of standardisation',min:1,max:10,value:3,target:8,weight:4},{key:'speed',label:'Priority for fast entry',min:1,max:10,value:5,target:8,weight:4}]},apply:{heading:'Recommend a growth route',intro:'Be clear whether you are recommending an independent company route or a franchise arrangement.',outputName:'growth-route recommendation',outputIntro:'This educational note should lead to detailed commercial and legal due diligence.',fields:[{label:'Founder’s dominant priority',help:'Choose autonomy, system support, capital route, brand or speed.',placeholder:'The most important priority is…'},{label:'Recommended route',help:'State independent corporation/company route or franchise arrangement.',placeholder:'I recommend…'},{label:'Trade-off to accept',help:'Explain what the founder gives up or must manage.',placeholder:'The founder must accept/manage…'}]},complete:{...common.complete,takeaways:['A company is a legal ownership form; a franchise is a contractual growth arrangement.','Franchising exchanges some autonomy for brand and system support.','Independent scaling gives control but requires building the system and brand.'],transfer:'Could a franchisee itself operate through a company? What does that reveal about the difference between the two concepts?'}},
  14:{title:'Small Enterprise Launch Mission',subtitle:'Put the dependencies in order so the venture can move from plan to controlled operation.',mission:'Build a practical launch pathway for a small natural-fibre product enterprise.',image:img.launch,context:'A founder team near Coimbatore wants to convert agricultural fibre into simple consumer products.',learn:{why:'Enterprise setup is a connected system. Premises, finance, approvals, suppliers, people and production must support one another.',steps:[{title:'Validate before committing',text:'Clarify the opportunity, product, customer, resource need and business model.'},{title:'Build the operating base',text:'Choose form, finance, location, registrations, suppliers, equipment and people in a logical dependency order.'},{title:'Trial before scaling',text:'Pilot production, check quality and readiness, then launch and monitor.'}],terms:[{term:'Project report/business plan',meaning:'A structured document connecting market, operations, organisation, finance, risk and implementation.'},{term:'Commissioning',meaning:'Preparing and verifying equipment or facilities for safe, intended operation.'}],example:'Do not buy production equipment before confirming product requirements, capacity, finance and a feasible location.'},activity:{mode:'sequence',max:8,heading:'Build the launch pathway',intro:'The cards combine strategic, legal and operational tasks.',instruction:'Arrange them into a sensible dependency sequence. Real projects may overlap, but this order protects major decisions.',success:'The pathway validates the plan before major commitment and places trial production before commercial launch.',retry:'Begin with evidence and planning; establish the legal/resource base before procurement; verify through a trial before launch.',items:[{name:'Commercial launch and monitoring',clue:'Begin controlled sales and track quality, demand, cash and capacity.',order:8,start:0},{name:'Select form and prepare project plan',clue:'Define ownership, market, operations, finance, risk and milestones.',order:2,start:1},{name:'Trial production and quality check',clue:'Run the process, find gaps and verify output before full launch.',order:7,start:2},{name:'Identify and validate opportunity',clue:'Confirm the customer problem, demand and initial solution logic.',order:1,start:3},{name:'Arrange finance and location',clue:'Match funding and premises to realistic capacity and requirements.',order:3,start:4},{name:'Complete applicable registrations and approvals',clue:'Identify requirements based on activity, location, form and workforce.',order:4,start:5},{name:'Procure, install and commission resources',clue:'Acquire equipment/materials and confirm operational readiness.',order:5,start:6},{name:'Recruit, train and establish procedures',clue:'Assign responsibilities, safety, quality and daily workflow.',order:6,start:7}]},apply:{heading:'Create a launch checkpoint',intro:'Convert one stage into an owner–metric–date commitment.',outputName:'small-enterprise launch card',outputIntro:'A milestone becomes useful when responsibility and evidence are explicit.',fields:[{label:'Next milestone',help:'Name one specific setup outcome.',placeholder:'Complete/verify/commission…'},{label:'Owner and evidence',help:'Who is responsible, and what proves completion?',placeholder:'Owner: … Evidence: …'},{label:'Risk and response',help:'Name one likely delay or failure and a preventive action.',placeholder:'If…, we will…'}]},complete:{...common.complete,takeaways:['Validate and plan before committing major resources.','Setup tasks have dependencies and applicable approvals vary by venture.','Trial production and quality checks should precede full launch.'],transfer:'Which two setup activities can safely overlap, and what coordination would they require?'}},
  15:{title:'MSME Registration & Venture Architect',subtitle:'Finish Unit II by connecting opportunity, product, ownership, setup and official registration.',mission:'Identify accurate Udyam facts, then prepare an integrated launch brief for a small enterprise.',image:img.launch,context:'A founder is preparing a manufacturing-and-service venture for formal launch in Tamil Nadu.',learn:{why:'Registration should follow accurate official guidance and fit within a wider venture plan—not become a substitute for validation, operations or financial thinking.',steps:[{title:'Use the official source',text:'Udyam Registration is filed on the Government of India’s official portal. Avoid look-alike fee-charging sites.'},{title:'Prepare accurate identity and enterprise details',text:'The official process uses Aadhaar and linked PAN/GST information as applicable, plus business, plant/unit, activity and bank details.'},{title:'Connect registration to the venture',text:'Confirm business form, product plan, setup requirements and evidence before declaring facts.'}],terms:[{term:'Udyam Registration',meaning:'The official Government of India registration process for qualifying micro, small and medium enterprises.'},{term:'Self-declaration',meaning:'Information is declared by the applicant; deliberate misrepresentation can have consequences.'}],example:'The official portal states that filing is free and paperless, no documents are uploaded for registration, and an online certificate with a permanent number is issued after completion. Verify current requirements on the portal before filing.'},activity:{mode:'detective',max:8,heading:'Official-fact document detective',intro:'The statements reflect official Udyam guidance checked in August 2026.',instruction:'Classify every statement as Official-process fact, Venture preparation or Red flag. Read the explanation before continuing.',categories:['Official-process fact','Venture preparation','Red flag'],evidence:[{text:'Use udyamregistration.gov.in and confirm it is the Government of India portal.',answer:'Official-process fact',feedback:'The official portal warns that no private portal or agent is authorised to undertake Udyam Registration.'},{text:'Pay an agent a mandatory registration fee to receive the certificate.',answer:'Red flag',feedback:'The official portal states that Udyam Registration is free.'},{text:'Validate the customer problem and product before committing major resources.',answer:'Venture preparation',feedback:'This is essential planning, but it is not itself a portal registration step.'},{text:'Prepare Aadhaar and PAN/GST-linked details as applicable to the organisation and law.',answer:'Official-process fact',feedback:'The official form and guidance explain the identity details required for different business forms.'},{text:'Upload a scanned project report and property file as compulsory Udyam documents.',answer:'Red flag',feedback:'Official guidance describes the process as paperless and says no documents or proof are uploaded for registration.'},{text:'Choose business form, location, capacity and operating responsibilities.',answer:'Venture preparation',feedback:'These decisions make the enterprise coherent and help ensure declared information is accurate.'},{text:'One registration may include multiple manufacturing or service activities.',answer:'Official-process fact',feedback:'Official guidance allows multiple activities under one Udyam Registration.'},{text:'Use old MSME limits without checking the effective date.',answer:'Red flag',feedback:'Classification limits changed from 1 April 2025; always verify current thresholds on the official portal.'}]},apply:{heading:'Complete the Venture Architect challenge',intro:'Bring the whole unit together in one compact founder brief.',outputName:'Unit II venture architecture brief',outputIntro:'This is a learning artefact. Confirm actual legal, tax and registration decisions with current official guidance and qualified professionals.',fields:[{label:'Opportunity and selected idea',help:'State the customer problem, evidence and solution.',placeholder:'Our customer…, evidence shows…, so we will test…'},{label:'Product-development gate',help:'Name the prototype/test and go-or-revise evidence.',placeholder:'Before launch we must prove…'},{label:'Business form and setup logic',help:'Recommend a form and name the next setup milestone.',placeholder:'We recommend… because… Next we will…'},{label:'Registration readiness',help:'State official source and identity/enterprise information to verify.',placeholder:'We will use the official Udyam portal and verify…'}]},complete:{...common.complete,title:'Unit II venture architect achieved',message:'You have connected idea creation, evidence, product decisions, venture form, enterprise setup and official registration into one founder pathway.',takeaways:['Opportunities become ventures through repeated evidence and decisions.','Product planning, business form and enterprise setup must support the same venture logic.','Use current official sources for registration and professional guidance for real formation decisions.'],transfer:'Which Unit II decision creates the greatest risk if it is based on assumption rather than evidence? Explain your choice.'}}
  };
  window.LESSON={...common,...lessons[n],number:n};
})();
